// RegisterHandlersOptions configures RegisterHandlersWithOptions.
type RegisterHandlersOptions struct {
	// BaseURL is prepended to every registered path so the API can be served
	// under a prefix.
	BaseURL string
	// OperationMiddlewares lets the caller attach per-operation middleware at
	// registration time. The map key is the OpenAPI `operationId` value as it
	// appears in the spec (the raw, un-normalized form). Operations that have
	// no entry are registered with no extra middleware. A nil map disables
	// per-operation middleware entirely.
	OperationMiddlewares map[string][]echo.MiddlewareFunc
}

// RegisterHandlers adds each server route to the EchoRouter.
func RegisterHandlers(router EchoRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, RegisterHandlersOptions{})
}

// RegisterHandlersWithBaseURL registers handlers and prepends BaseURL to the
// paths so the API can be served under a prefix.
func RegisterHandlersWithBaseURL(router EchoRouter, si ServerInterface, baseURL string) {
	RegisterHandlersWithOptions(router, si, RegisterHandlersOptions{BaseURL: baseURL})
}

// RegisterHandlersWithOptions registers handlers using the supplied options,
// including any per-operation middleware.
func RegisterHandlersWithOptions(router EchoRouter, si ServerInterface, options RegisterHandlersOptions) {

	wrapper := ServerInterfaceWrapper{
		Handler: si,
	}

	router.POST(options.BaseURL+"/auth/sign-up", wrapper.SignUp, options.OperationMiddlewares["signUp"]...)
	router.POST(options.BaseURL+"/auth/sign-in", wrapper.SignIn, options.OperationMiddlewares["signIn"]...)
	router.POST(options.BaseURL+"/auth/refresh", wrapper.Refresh, options.OperationMiddlewares["refresh"]...)
	router.POST(options.BaseURL+"/auth/logout", wrapper.Logout, options.OperationMiddlewares["logout"]...)
	router.GET(options.BaseURL+"/auth/:provider/sign-in", wrapper.OauthSignIn, options.OperationMiddlewares["oauthSignIn"]...)
	router.GET(options.BaseURL+"/auth/:provider/callback", wrapper.OauthCallback, options.OperationMiddlewares["oauthCallback"]...)
	router.POST(options.BaseURL+"/sync/push", wrapper.SyncPush, options.OperationMiddlewares["syncPush"]...)
	router.GET(options.BaseURL+"/sync/pull", wrapper.SyncPull, options.OperationMiddlewares["syncPull"]...)
	router.GET(options.BaseURL+"/sync/snapshot", wrapper.SyncSnapshot, options.OperationMiddlewares["syncSnapshot"]...)
	router.POST(options.BaseURL+"/scan/code", wrapper.ScanCode, options.OperationMiddlewares["scanCode"]...)
	router.POST(options.BaseURL+"/scan/photo", wrapper.ScanPhoto, options.OperationMiddlewares["scanPhoto"]...)
	router.POST(options.BaseURL+"/photos/upload-url", wrapper.CreatePhotoUploadUrl, options.OperationMiddlewares["createPhotoUploadUrl"]...)
	router.GET(options.BaseURL+"/photos/:key/url", wrapper.GetPhotoUrl, options.OperationMiddlewares["getPhotoUrl"]...)

}

